START TRANSACTION;
CREATE TABLE ai_practice_sessions (
    "PracticeSessionId" integer GENERATED BY DEFAULT AS IDENTITY,
    "LearnerId" integer NOT NULL,
    "CourseId" integer,
    "LessonId" integer,
    "PracticeMode" character varying(10) NOT NULL,
    "AudioUrl" character varying(1000) NOT NULL,
    "Status" character varying(20) NOT NULL,
    "ExpectedText" character varying(5000),
    "ErrorMessage" character varying(1000),
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ai_practice_sessions" PRIMARY KEY ("PracticeSessionId"),
    CONSTRAINT "FK_ai_practice_sessions_courses_CourseId" FOREIGN KEY ("CourseId") REFERENCES courses ("CourseID") ON DELETE RESTRICT,
    CONSTRAINT "FK_ai_practice_sessions_lessons_LessonId" FOREIGN KEY ("LessonId") REFERENCES lessons ("LessonID") ON DELETE RESTRICT,
    CONSTRAINT "FK_ai_practice_sessions_users_LearnerId" FOREIGN KEY ("LearnerId") REFERENCES users ("UserID") ON DELETE RESTRICT
);

CREATE TABLE ai_practice_feedbacks (
    "PracticeFeedbackId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PracticeSessionId" integer NOT NULL,
    "LearnerId" integer NOT NULL,
    "ModelVersion" character varying(50) NOT NULL,
    "CheckpointEpoch" integer NOT NULL,
    "LLMProvider" character varying(100) NOT NULL,
    "LLMModel" character varying(100) NOT NULL,
    "PredictionJson" text NOT NULL,
    "FeedbackJson" text NOT NULL,
    "Summary" text NOT NULL,
    "ExpectedText" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ai_practice_feedbacks" PRIMARY KEY ("PracticeFeedbackId"),
    CONSTRAINT "FK_ai_practice_feedbacks_ai_practice_sessions_PracticeSessionId" FOREIGN KEY ("PracticeSessionId") REFERENCES ai_practice_sessions ("PracticeSessionId") ON DELETE CASCADE,
    CONSTRAINT "FK_ai_practice_feedbacks_users_LearnerId" FOREIGN KEY ("LearnerId") REFERENCES users ("UserID") ON DELETE RESTRICT
);

CREATE INDEX "IX_ai_practice_feedbacks_LearnerId" ON ai_practice_feedbacks ("LearnerId");

CREATE UNIQUE INDEX "IX_ai_practice_feedbacks_PracticeSessionId" ON ai_practice_feedbacks ("PracticeSessionId");

CREATE INDEX "IX_ai_practice_sessions_CourseId_LessonId_CreatedAt" ON ai_practice_sessions ("CourseId", "LessonId", "CreatedAt");

CREATE INDEX "IX_ai_practice_sessions_LearnerId_CreatedAt" ON ai_practice_sessions ("LearnerId", "CreatedAt");

CREATE INDEX "IX_ai_practice_sessions_LessonId" ON ai_practice_sessions ("LessonId");

